INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_esp-10_PrimerGrado', 'Fase 6', 'Secundaria', 'Lenguajes', 'Español', 'Primer Grado', 'Los géneros periodísticos y sus recursos para comunicar sucesos significativos familiares, escolares, comunitarios y sociales.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
