INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-8_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Primer Grado', 'Construcción y propiedades de las figuras planas y cuerpos.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_PrimerGrado_1', 'CONT_mat-8_PrimerGrado', 'Primer Grado', 1, 'Utiliza la regla y el compás para trazar: punto medio, mediatriz de un segmento, segmentos y ángulos congruentes, bisectriz de un ángulo, rectas perpendiculares y rectas paralelas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_PrimerGrado_2', 'CONT_mat-8_PrimerGrado', 'Primer Grado', 2, 'Identifica y traza las rectas notables en triángulos y cuadriláteros.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_PrimerGrado_3', 'CONT_mat-8_PrimerGrado', 'Primer Grado', 3, 'Construye y clasifica triángulos y cuadriláteros a partir del análisis de distinta información.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-8_SegundoGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Segundo Grado', 'Construcción y propiedades de las figuras planas y cuerpos.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_SegundoGrado_1', 'CONT_mat-8_SegundoGrado', 'Segundo Grado', 1, 'Construye con regla y compás polígonos regulares con distinta información.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_SegundoGrado_2', 'CONT_mat-8_SegundoGrado', 'Segundo Grado', 2, 'Identifica y usa las relaciones entre figuras en la construcción de teselados.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-8_TercerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Tercer Grado', 'Construcción y propiedades de las figuras planas y cuerpos.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_TercerGrado_1', 'CONT_mat-8_TercerGrado', 'Tercer Grado', 1, 'Aplica las propiedades de la congruencia y semejanza de triángulos al construir y resolver problemas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_TercerGrado_2', 'CONT_mat-8_TercerGrado', 'Tercer Grado', 2, 'Reconoce las propiedades de los sólidos.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_TercerGrado_3', 'CONT_mat-8_TercerGrado', 'Tercer Grado', 3, 'Explora la generación de sólidos de revolución a partir de figuras planas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-8_TercerGrado_4', 'CONT_mat-8_TercerGrado', 'Tercer Grado', 4, 'Explora y construye desarrollos planos de diferentes figuras tridimensionales, cilindros, pirámides y conos.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-9_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Primer Grado', 'Medición y cálculo en diferentes contextos.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_PrimerGrado_1', 'CONT_mat-9_PrimerGrado', 'Primer Grado', 1, 'Introduce la idea de distancia entre dos puntos como la longitud del segmento que los une.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_PrimerGrado_2', 'CONT_mat-9_PrimerGrado', 'Primer Grado', 2, 'Encuentra la distancia de un punto a una recta y la distancia entre dos rectas paralelas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_PrimerGrado_3', 'CONT_mat-9_PrimerGrado', 'Primer Grado', 3, 'Explora la desigualdad del triángulo.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_PrimerGrado_4', 'CONT_mat-9_PrimerGrado', 'Primer Grado', 4, 'Obtiene y aplica fórmulas o usa otras estrategias para calcular el perímetro y el área de polígonos regulares e irregulares y del círculo.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-9_SegundoGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Segundo Grado', 'Medición y cálculo en diferentes contextos.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_SegundoGrado_1', 'CONT_mat-9_SegundoGrado', 'Segundo Grado', 1, 'Resuelve problemas que implican conversiones en múltiplos y submúltiplos del metro, litro, kilogramo y de unidades del sistema inglés (yarda, pulgada, galón, onza y libra).') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_SegundoGrado_2', 'CONT_mat-9_SegundoGrado', 'Segundo Grado', 2, 'Utiliza estrategias diversas para determinar el perímetro y el área de figuras compuestas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-9_TercerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Tercer Grado', 'Medición y cálculo en diferentes contextos.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_TercerGrado_1', 'CONT_mat-9_TercerGrado', 'Tercer Grado', 1, 'Usa diferentes estrategias para calcular el volumen de prismas, pirámides y cilindros.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_TercerGrado_2', 'CONT_mat-9_TercerGrado', 'Tercer Grado', 2, 'Formula, justifica y usa el teorema de Pitágoras al resolver problemas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-9_TercerGrado_3', 'CONT_mat-9_TercerGrado', 'Tercer Grado', 3, 'Resuelve problemas utilizando las razones trigonométricas seno, coseno y tangente.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-10_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Primer Grado', 'Azar y probabilidad.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_PrimerGrado_1', 'CONT_mat-10_PrimerGrado', 'Primer Grado', 1, 'Compara cualitativamente dos o más eventos a partir de sus resultados posibles, usa relaciones como: ''es más probable que...'', ''es menos probable que...''.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_PrimerGrado_2', 'CONT_mat-10_PrimerGrado', 'Primer Grado', 2, 'Identifica eventos en los que interviene el azar, determina el espacio muestral y experimenta.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_PrimerGrado_3', 'CONT_mat-10_PrimerGrado', 'Primer Grado', 3, 'Identifica diversos procedimientos de conteo y resuelve problemas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-10_SegundoGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Segundo Grado', 'Azar y probabilidad.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_SegundoGrado_1', 'CONT_mat-10_SegundoGrado', 'Segundo Grado', 1, 'Realiza experimentos aleatorios y registra los resultados en una tabla de frecuencia como la transición de la probabilidad frecuencial a la teórica.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_SegundoGrado_2', 'CONT_mat-10_SegundoGrado', 'Segundo Grado', 2, 'Analiza las características de la medida de la probabilidad y su equivalencia y representación en números decimales, fraccionarios y porcentajes.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_mat-10_TercerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Matemáticas', 'Tercer Grado', 'Azar y probabilidad.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_TercerGrado_1', 'CONT_mat-10_TercerGrado', 'Tercer Grado', 1, 'Resuelve problemas donde se analicen las características de eventos complementarios y eventos mutuamente excluyentes e independientes.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_TercerGrado_2', 'CONT_mat-10_TercerGrado', 'Tercer Grado', 2, 'Resuelve problemas donde se calcule la probabilidad de ocurrencia de dos eventos mutuamente excluyentes y de eventos complementarios (regla de la suma).') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_mat-10_TercerGrado_3', 'CONT_mat-10_TercerGrado', 'Tercer Grado', 3, 'Resuelve problemas donde se calcule la probabilidad de ocurrencia de dos eventos independientes (regla del producto).') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_bio-1_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Biología', 'Primer Grado', 'Funcionamiento del cuerpo humano coordinado por los sistemas nervioso y endocrino.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-1_PrimerGrado_1', 'CONT_bio-1_PrimerGrado', 'Primer Grado', 1, 'Explica la participación de los sistemas nervioso y endocrino en la coordinación de las funciones del cuerpo humano; reconoce el papel general de las hormonas y sus efectos en la maduración sexual y en la reproducción.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-1_PrimerGrado_2', 'CONT_bio-1_PrimerGrado', 'Primer Grado', 2, 'Explica los efectos del consumo de sustancias adictivas en el sistema nervioso y en el funcionamiento integral del cuerpo humano; argumenta la importancia de evitar su consumo a partir del análisis de sus implicaciones en la salud, la sexualidad, la economía y la sociedad.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_bio-2_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Biología', 'Primer Grado', 'Salud sexual y reproductiva: prevención de infecciones de transmisión sexual y del embarazo en adolescentes.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-2_PrimerGrado_1', 'CONT_bio-2_PrimerGrado', 'Primer Grado', 1, 'Compara las maneras en que la cultura influye en el concepto de sexualidad; reconoce que todas las culturas tienen maneras distintas de comprender el género, la sexualidad y la reproducción; y reflexiona acerca de que el inicio de la actividad sexual debe ser de manera consensuada.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-2_PrimerGrado_2', 'CONT_bio-2_PrimerGrado', 'Primer Grado', 2, 'Cuestiona creencias, estereotipos y costumbres que impactan negativamente la salud sexual y reproductiva de niñas y mujeres; reconoce la importancia de la igualdad de género y la responsabilidad compartida del hombre y la mujer en la prevención del embarazo en la adolescencia.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-2_PrimerGrado_3', 'CONT_bio-2_PrimerGrado', 'Primer Grado', 3, 'Compara la efectividad de los métodos anticonceptivos como apoyo para planificar el embarazo desde la perspectiva del proyecto de vida; valora la efectividad del condón por su doble protección.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_bio-3_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Biología', 'Primer Grado', 'Prevención de enfermedades relacionadas con la alimentación y el consumo de alimentos ultraprocesados.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-3_PrimerGrado_1', 'CONT_bio-3_PrimerGrado', 'Primer Grado', 1, 'Identifica causas de la obesidad y la diabetes relacionadas con la dieta y el sedentarismo, a fin de formular su proyecto de vida saludable; incluye factores protectores y propone acciones para reducir factores de riesgo.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-3_PrimerGrado_2', 'CONT_bio-3_PrimerGrado', 'Primer Grado', 2, 'Formula hipótesis acerca de las consecuencias de carencia o exceso de nutrimentos en la dieta; interpreta datos que muestran la correlación entre la incidencia de enfermedades como la caries e hipertensión y el consumo de exceso de sal, azúcar y grasas saturadas.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_bio-4_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Biología', 'Primer Grado', 'La biodiversidad como expresión del cambio de los seres vivos en el tiempo.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-4_PrimerGrado_1', 'CONT_bio-4_PrimerGrado', 'Primer Grado', 1, 'Analiza información acerca del estado de la biodiversidad local a partir de fuentes directas, orales, escritas, audiovisuales o Internet, expone razones sobre su importancia cultural, biológica, estética y ética; propone acciones para su cuidado.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-4_PrimerGrado_2', 'CONT_bio-4_PrimerGrado', 'Primer Grado', 2, 'Indaga las principales aportaciones de Darwin y Wallace, las identifica como una de las explicaciones más fundamentadas acerca del origen de la biodiversidad y reflexiona acerca de cómo han cambiado.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_bio-5_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Biología', 'Primer Grado', 'El calentamiento global como una consecuencia de la alteración de los ciclos biogeoquímicos en los ecosistemas.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-5_PrimerGrado_1', 'CONT_bio-5_PrimerGrado', 'Primer Grado', 1, 'Representa la transferencia de materia y energía entre los organismos de un ecosistema mediante redes y pirámides tróficas; elabora explicaciones, inferencias y predicciones consistentes.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-5_PrimerGrado_2', 'CONT_bio-5_PrimerGrado', 'Primer Grado', 2, 'Identifica interacciones de competencia e interdependencia en el ecosistema local y explica cómo regulan el funcionamiento y mantenimiento en la dinámica general del ecosistema.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-5_PrimerGrado_3', 'CONT_bio-5_PrimerGrado', 'Primer Grado', 3, 'Analiza las prácticas de consumo que han alterado los ciclos biogeoquímicos del carbono y el nitrógeno, sus efectos asociados al calentamiento global y sus impactos en el medio ambiente y la salud.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_bio-6_PrimerGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Biología', 'Primer Grado', 'Las vacunas: su relevancia en el control de algunas enfermedades infecciosas.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-6_PrimerGrado_1', 'CONT_bio-6_PrimerGrado', 'Primer Grado', 1, 'Describe las características generales de las bacterias y los virus; formula hipótesis en torno al por qué de la rápida propagación de las enfermedades infecciosas que causan, y las contrasta con evidencias con sustento científico.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_bio-6_PrimerGrado_2', 'CONT_bio-6_PrimerGrado', 'Primer Grado', 2, 'Valora la importancia y la necesidad de proteger la salud con el uso de las vacunas para el control de algunas enfermedades infecciosas; evalúa sus riesgos y beneficios sociales y económicos.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_fis-1_SegundoGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Física', 'Segundo Grado', 'El pensamiento científico, una forma de plantear y solucionar problemas y su incidencia en la transformación de la sociedad.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
