INSERT INTO nem_pdas (id, contenido_id, grado, orden, descripcion) VALUES ('PDA_fis-1_SegundoGrado_2', 'CONT_fis-1_SegundoGrado', 'Segundo Grado', 2, 'Indaga en diferentes fuentes de consulta las aportaciones de mujeres y hombres en el desarrollo de la Física y su contribución al conocimiento científico y tecnológico.') ON CONFLICT (id) DO UPDATE SET descripcion = EXCLUDED.descripcion;
INSERT INTO nem_contenidos (id, fase, nivel, campo_formativo, disciplina, grado, contenido) VALUES ('CONT_fis-2_SegundoGrado', 'Fase 6', 'Secundaria', 'Saberes y Pensamiento Científico', 'Física', 'Segundo Grado', 'Unidades y medidas utilizados en Física.') ON CONFLICT (id) DO UPDATE SET contenido = EXCLUDED.contenido;
