-- ============================================================================
-- SCRIPT DE MIGRACIÓN Y SEED DATA: CURRÍCULO NUEVA ESCUELA MEXICANA (NEM 2022-2026)
-- FASES SINTÉTICAS: FASE 2, 3, 4, 5 Y 6 (Preescolar, Primaria y Secundaria)
-- Compatible con PostgreSQL y Supabase
-- ============================================================================

-- 1. TABLA: contenidos_sinteticos
CREATE TABLE IF NOT EXISTS nem_contenidos (
    id VARCHAR(100) PRIMARY KEY,
    fase VARCHAR(20) NOT NULL,
    nivel VARCHAR(50) NOT NULL,
    campo_formativo VARCHAR(100) NOT NULL,
    disciplina VARCHAR(100) NOT NULL,
    grado VARCHAR(50) NOT NULL,
    contenido TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. TABLA: pdas (Procesos de Desarrollo de Aprendizaje)
CREATE TABLE IF NOT EXISTS nem_pdas (
    id VARCHAR(100) PRIMARY KEY,
    contenido_id VARCHAR(100) REFERENCES nem_contenidos(id) ON DELETE CASCADE,
    grado VARCHAR(50) NOT NULL,
    orden INT NOT NULL,
    descripcion TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ÍNDICES PARA CONSULTAS RÁPIDAS EN CASCADA
CREATE INDEX IF NOT EXISTS idx_nem_contenidos_filtro ON nem_contenidos (nivel, grado, campo_formativo, disciplina);
CREATE INDEX IF NOT EXISTS idx_nem_pdas_contenido ON nem_pdas (contenido_id, grado);

-- 3. INSERTAR DATOS RELACIONALES (SEED DATA)
